package main

import (
 "fmt"
 "go/ast"
 "go/parser"
 "go/token"
 "os"
 "path/filepath"
 "sort"
 "strconv"
 "strings"
 "unicode"
 "unicode/utf8"
)

type Import struct {Name, Path string}
type Header struct {Comments []string; Package string; Imports []*Import; Code []byte}
type Output struct {Path string; Code []byte; Names []string}
type parsedPackage struct {
 fs *token.FileSet
 file *ast.File
 data []byte
 path string
 files []*ast.File
 types map[string]*ast.TypeSpec
 imports []*Import
}

func sourceFile(name string) bool {return strings.HasSuffix(name,".go") && !strings.HasSuffix(name,"_test.go")}
func listInputs(path string) ([]string,error) {
 recursive:=strings.HasSuffix(path,"/...") || path=="..."
 if recursive {path=strings.TrimSuffix(path,"...");if path==""{path="."}}
 abs,e:=filepath.Abs(path);if e!=nil{return nil,e}
 stat,e:=os.Stat(abs);if e!=nil {return nil,fmt.Errorf("input.Files: os.Stat: %v\n",e)}
 if !stat.IsDir() {
  if !strings.HasSuffix(abs,".go") {return nil,fmt.Errorf("input.Files: no Go source files found at %s",abs)}
  if strings.HasSuffix(abs,"_test.go") {return nil,nil}
  return []string{abs},nil
 }
 var files []string
 var walk func(string) error
 walk=func(dir string) error {
  entries,e:=os.ReadDir(dir);if e!=nil{return e}
  if recursive {for _,ent:=range entries{if ent.IsDir(){if e:=walk(filepath.Join(dir,ent.Name()));e!=nil{return e}}}}
  for _,ent:=range entries{if !ent.IsDir() && sourceFile(ent.Name()){files=append(files,filepath.Join(dir,ent.Name()))}}
  return nil
 }
 if e=walk(abs);e!=nil{return nil,fmt.Errorf("input.Files: %v",e)}
 return files,nil
}

func generatePath(path string,o *Options) ([]Output,error) {
 paths,e:=listInputs(path);if e!=nil{return nil,e}
 var out []Output
 for _,p:=range paths {
  v,e:=generateFile(p,o);if e!=nil{return nil,e}
  if v!=nil {out=append(out,*v)}
 }
 return out,nil
}

func parseSource(path string) (*parsedPackage,error) {
 p:=&parsedPackage{fs:token.NewFileSet(),path:path,types:map[string]*ast.TypeSpec{}}
 var e error
 p.data,e=os.ReadFile(path);if e!=nil {return nil,fmt.Errorf("Parser.Parse source file: %v",e)}
 p.file,e=parser.ParseFile(p.fs,path,p.data,parser.ParseComments)
 if e!=nil {return nil,fmt.Errorf("Parser.Parse source file: target parser.ParseFile(): %v",e)}
 p.files=append(p.files,p.file)
 entries,e:=os.ReadDir(filepath.Dir(path));if e!=nil{return nil,e}
 for _,ent:=range entries{
  name:=filepath.Join(filepath.Dir(path),ent.Name())
  if ent.IsDir() || !sourceFile(ent.Name()) || name==path {continue}
  f,e:=parser.ParseFile(p.fs,name,nil,parser.ParseComments)
  if e!=nil{return nil,fmt.Errorf("Parser.Parse source file: other file parser.ParseFile: %v",e)}
  p.files=append(p.files,f)
 }
 for _,f:=range p.files {
  for _,i:=range f.Imports {
   n:="";if i.Name!=nil{n=i.Name.Name}
   p.imports=append(p.imports,&Import{n,i.Path.Value})
  }
  for _,d:=range f.Decls {if g,ok:=d.(*ast.GenDecl);ok {for _,s:=range g.Specs{if t,ok:=s.(*ast.TypeSpec);ok{p.types[t.Name.Name]=t}}}}
 }
 return p,nil
}

func (p *parsedPackage) underlying(x ast.Expr,seen map[string]bool) string {
 switch t:=x.(type) {
 case *ast.Ident:
  if basicTypes[t.Name] {if t.Name=="byte"{return "uint8"};if t.Name=="rune"{return "int32"};return t.Name}
  if t.Name=="any" {return "any"}
  if t.Name=="error" {return "interface{Error() string}"}
  if seen[t.Name]{return ""}
  if d:=p.types[t.Name];d!=nil {seen[t.Name]=true;v:=p.underlying(d.Type,seen);delete(seen,t.Name);return v}
  return ""
 case *ast.SelectorExpr:return ""
 case *ast.StructType:
  var fields []string
  for _,f:=range t.Fields.List{n:=nodeString(f.Type);for _,name:=range f.Names{fields=append(fields,name.Name+" "+n)};if len(f.Names)==0{fields=append(fields,n)}}
  return "struct{"+strings.Join(fields,"; ")+"}"
 default:return nodeString(x)
 }
}
func (p *parsedPackage) expression(x ast.Expr) *Expression {
 e:=&Expression{}
 if a,ok:=x.(*ast.Ellipsis);ok {e.IsVariadic=true;x=a.Elt}
 if a,ok:=x.(*ast.StarExpr);ok {e.IsStar=true;x=a.X}
 e.Value=nodeString(x)
 e.Underlying=p.underlying(x,map[string]bool{})
