}

type codeBuilder struct {strings.Builder}
func (b *codeBuilder) line(s string,args ...interface{}) {if len(args)>0{s=fmt.Sprintf(s,args...)};b.WriteString(s);b.WriteByte('\n')}

func defaultHeader(h *Header) string {
 var b codeBuilder
 for _,c:=range h.Comments{b.line(c)}
 b.line("package %s",h.Package)
 b.line("")
 if len(h.Imports)>0 {
  b.line("import (")
  for _,i:=range h.Imports {if i.Name!=""{b.line(i.Name+" "+i.Path)}else{b.line(i.Path)}}
  b.line(")")
 }
 return b.String()
}
func renderFile(h *Header,funcs []*Function,o *Options) ([]byte,error) {
 if o.TemplateDir=="" && o.Template!="" && o.Template!="testify" {return nil,fmt.Errorf("output.Process: loading custom templates of name: templates.ParseFS: template: pattern matches no files: `*.tmpl`")}
 testify:=o.Template=="testify" && o.TemplateDir==""
 tm:=template.New("root").Funcs(template.FuncMap{
  "renderHeader":defaultHeader,
  "renderFunction":func(d functionData)string{return defaultFunction(d.Function,o,testify)},
  "ToLower":strings.ToLower,"ToUpper":strings.ToUpper,"ToTitle":strings.Title,
  "lower":strings.ToLower,"upper":strings.ToUpper,
  "title":strings.Title,
 })
 tm,_=tm.Parse(`{{define "header"}}{{renderHeader .}}{{end}}{{define "function"}}{{renderFunction .}}{{end}}`)
 if o.TemplateDir!="" {
  entries,e:=os.ReadDir(o.TemplateDir);if e!=nil{return nil,fmt.Errorf("output.Process: loading custom templates: ioutil.ReadDir: %v",e)}
  var files []string
