 }
 parseErr:=func(e error)([]*AICase,error){return nil,fmt.Errorf("parse Go test cases: %v\n\nLLM Response:\n%s",e,response)}
 if clean==""{return parseErr(fmt.Errorf("no test cases found in response"))}
 src:=""
 if strings.Contains(clean,"tests :=") || strings.Contains(clean,"tests:=") {src="package main\n\nfunc test(){\n"+clean+"\n}"}else if strings.HasPrefix(clean,"[]struct") {src="package main\n\nfunc test(){\ntests := "+clean+"\n}"}else{
