func populateAI(funcs []*Function,o *Options) error {
 client:=&http.Client{Timeout:10*time.Second}
 response,e:=client.Get(strings.TrimRight(o.AIEndpoint,"/")+"/api/tags")
 if e!=nil {return fmt.Errorf("output.Process: AI provider ollama is not available - ensure Ollama is running at %s",o.AIEndpoint)}
 io.Copy(io.Discard,response.Body);response.Body.Close()
 if response.StatusCode!=200 {return fmt.Errorf("output.Process: AI provider ollama is not available - ensure Ollama is running at %s",o.AIEndpoint)}
 for _,f:=range funcs {
  var last error
  for attempt:=0;attempt<3;attempt++ {
   prev:="";if last!=nil{prev=last.Error()}
   request:=map[string]interface{}{"model":o.AIModel,"options":map[string]interface{}{"seed":42,"temperature":0},"prompt":aiPrompt(f,o,prev),"stream":false}
   data,_:=json.Marshal(request)
   resp,e:=client.Post(strings.TrimRight(o.AIEndpoint,"/")+"/api/generate","application/json",bytes.NewReader(data))
   if e!=nil{last=fmt.Errorf("ollama request failed: %v",e);continue}
   raw,e:=io.ReadAll(resp.Body);resp.Body.Close()
   if e!=nil{last=e;continue}
   if resp.StatusCode!=200{last=fmt.Errorf("ollama returned %d: %s",resp.StatusCode,raw);continue}
   var result struct{Response string;Error string}
   if e=json.Unmarshal(raw,&result);e!=nil{last=fmt.Errorf("decode ollama response: %v",e);continue}
   cases,e:=parseAICases(result.Response,f)
   if e!=nil{last=e;continue}
   f.Cases=cases;last=nil;break
