}
func parseAICases(response string,f *Function) ([]*AICase,error) {
 clean:=strings.TrimSpace(response)
 if i:=strings.Index(clean,"```");i>=0 {
  clean=clean[i+3:];if j:=strings.Index(clean,"\n");j>=0{clean=clean[j+1:]};if j:=strings.Index(clean,"```");j>=0{clean=clean[:j]};clean=strings.TrimSpace(clean)
 }
 parseErr:=func(e error)([]*AICase,error){return nil,fmt.Errorf("parse Go test cases: %v\n\nLLM Response:\n%s",e,response)}
 if clean==""{return parseErr(fmt.Errorf("no test cases found in response"))}
 src:=""
 if strings.Contains(clean,"tests :=") || strings.Contains(clean,"tests:=") {src="package main\n\nfunc test(){\n"+clean+"\n}"}else if strings.HasPrefix(clean,"[]struct") {src="package main\n\nfunc test(){\ntests := "+clean+"\n}"}else{
  src="package main\n\nfunc test(){\n"+strings.Replace(aiScaffold(f),"\t// TODO: Add test cases.",clean,1)+"\n}"
 }
 tree,e:=parser.ParseFile(token.NewFileSet(),"test.go",src,parser.AllErrors)
 if e!=nil{return parseErr(fmt.Errorf("parse Go code: %v",e))}
 var literal *ast.CompositeLit
 ast.Inspect(tree,func(n ast.Node)bool{
  if a,ok:=n.(*ast.AssignStmt);ok{for _,r:=range a.Rhs{if c,ok:=r.(*ast.CompositeLit);ok{literal=c;return false}}};return literal==nil
 })
 if literal==nil{return parseErr(fmt.Errorf("no test cases found in response"))}
 var cases []*AICase
 for _,elt:=range literal.Elts {
  lit,ok:=elt.(*ast.CompositeLit);if !ok{continue}
  c:=&AICase{Args:map[string]string{},Wants:make([]string,len(f.allResults()))}
  for _,elt:=range lit.Elts {kv,ok:=elt.(*ast.KeyValueExpr);if !ok{continue};key:=nodeString(kv.Key)
   switch key{
   case "name": c.Name,_=strconv.Unquote(nodeString(kv.Value))
   case "args":
    if args,ok:=kv.Value.(*ast.CompositeLit);ok{for _,a:=range args.Elts{if kv,ok:=a.(*ast.KeyValueExpr);ok{c.Args[nodeString(kv.Key)]=nodeString(kv.Value)}}}
   case "wantErr":c.WantErr=nodeString(kv.Value)=="true"
   default:
    if key=="want" && len(c.Wants)>0 {c.Wants[0]=nodeString(kv.Value)}else if strings.HasPrefix(key,"want") {if i,e:=strconv.Atoi(strings.TrimPrefix(key,"want"));e==nil&&i<len(c.Wants){c.Wants[i]=nodeString(kv.Value)}}else if f.Receiver!=nil{c.Receiver=nodeString(kv.Value)}
   }
  }
  if c.Name!=""{cases=append(cases,c)}
 }
 if len(cases)==0{return parseErr(fmt.Errorf("no test cases found in response"))}
 seen:=map[string]bool{}
 for _,c:=range cases {
  var values []string
  for _,p:=range f.inputArgs(){v,ok:=c.Args[p.ShortName()];if !ok{return nil,fmt.Errorf("test case %q missing argument: %s",c.Name,p.ShortName())};values=append(values,v)}
  key:=strings.Join(values,"\x00")
  if seen[key]{return nil,fmt.Errorf("generated test cases have duplicate values - need more diversity")};seen[key]=true
 }
 return cases,nil
}
func renderAICases(b *codeBuilder,f *Function,o *Options) {
 for _,c:=range f.Cases {
  if o.Named{b.line(strconv.Quote(c.Name)+": {")}else{b.line("{");b.line("name: "+strconv.Quote(c.Name)+",")}
  if len(f.inputArgs())>0{
   b.line("args: args{")
   for _,a:=range f.inputArgs(){b.line(a.ShortName()+": "+c.Args[a.ShortName()]+",")}
   b.line("},")
  }
  for i,r:=range f.allResults(){v:=c.Wants[i];if v==""{continue};b.line(r.WantName()+": "+v+",")}
  if f.ReturnsError{b.line("wantErr: "+strconv.FormatBool(c.WantErr)+",")}
  b.line("},")
 }
}
